+    const payload = runtimeEntry
+      ? buildPayload({
+          link,
+          linkIndex,
+          runtimeEntry,
+          msItemEntries,
+          sourceSpanEntries,
+          reviewQueueRefs,
+          sourceArtifacts,
+          paths,
+          schema: inputs.schema,
+        })
+      : null;
+    const validation = payload
+      ? validatePostAttemptReviewPayload({
+          schema: inputs.schema,
+          payload,
+          boundary: inputs.boundary,
+          fixtureId: link.link_id,
+        })
+      : {
+          status: 'fail',
+          errors: ['runtime_question_row_missing'],
+        };
+
+    return {
+      link_id: link.link_id ?? null,
+      question_key: questionKey,
+      candidate_status: validation.status === 'pass' ? 'schema_valid' : 'schema_invalid',
+      provenance_status: 'candidate_provenance_only',
+      ms_evidence: buildMsEvidence({
+        link,
+        linkIndex,
+        runtimeEntry,
+        msDocumentEntry,
+        msItemEntries,
+        sourceSpanEntries,
+        reviewQueueRefs,
+        paths,
+      }),
+      payload,
+      validation,
+      source_artifact_provenance: sourceArtifactProvenance(sourceArtifacts),
+    };
+  });
+}
+
+function dependencyBoundary(inputs) {
+  return {
+    checked_in_artifacts_only: true,
+    untracked_local_screenshot_dependency: false,
+    handoff_file_dependency: false,
+    remote_supabase_query_required: false,
+    remote_supabase_mutation_performed:
+      inputs.questionRuntimeManifest?.summary?.production_supabase_mutation_performed === true ||
+      inputs.semanticReviewQueue?.summary?.remote_supabase_mutation_performed === true,
+    production_rag_reindex_performed:
+      inputs.questionRuntimeManifest?.summary?.production_rag_reindex_performed === true ||
+      inputs.semanticReviewQueue?.summary?.production_rag_reindex_performed === true,
+    vector_store_mutation_performed:
+      inputs.questionRuntimeManifest?.summary?.vector_store_mutation_performed === true,
+    remote_disposable_supabase_write_performed:
+      inputs.questionRuntimeManifest?.summary?.remote_disposable_supabase_write_performed === true,
+    runtime_api_integration_performed: false,
+    frontend_ui_integration_performed: false,
+  };
+}
+
+function summarizeCandidates(payloadCandidates, inputs) {
+  const validCount = payloadCandidates.filter((candidate) => candidate.validation?.status === 'pass').length;
+  const criticalInputDiagnosticCount = arrayFrom(inputs.diagnostics)
+    .filter((diagnostic) => diagnostic?.severity === 'critical')
+    .length;
+  const status =
+    payloadCandidates.length > 0 &&
+    validCount === payloadCandidates.length &&
+    criticalInputDiagnosticCount === 0
+      ? 'pass'
+      : 'fail';
+  return {
+    validation_status: status,
+    candidate_count: payloadCandidates.length,
+    valid_candidate_count: validCount,
+    invalid_candidate_count: payloadCandidates.length - validCount,
+    question_runtime_row_count: countRows(inputs.questionRuntimeReadModel, 'rows'),
+    ms_candidate_link_count: countRows(inputs.msCandidateLinks, 'links'),
+    ms_raw_item_count: countRows(inputs.msRawItems, 'items'),
+    ms_source_span_count: countRows(inputs.msSourceSpans, 'source_spans'),
+    ms_selected_document_count: countRows(inputs.msSelectedDocuments, 'selected_documents'),
+    ms_layer_b_review_queue_count: countRows(inputs.msLayerBReviewQueue, 'review_queue'),
+    ms_review_queue_triage_count: countRows(inputs.msReviewQueueTriage, 'rows'),
+    source_asset_student_display_allowed_count: payloadCandidates.filter((candidate) => (
+      candidate.payload?.source_asset?.student_display_allowed === true
+    )).length,
+    authoritative_score_allowed_count: payloadCandidates.filter((candidate) => (
+      candidate.payload?.authoritative_score_allowed === true
+    )).length,
+    point_judgement_allowed_count: payloadCandidates.filter((candidate) => (
+      candidate.payload?.point_judgement_allowed === true
+    )).length,
+    official_ms_image_student_display_allowed_count: payloadCandidates.filter((candidate) => (
+      candidate.payload?.display_gates?.official_ms_image_student_display_allowed === true
+    )).length,
+    official_ms_text_student_display_allowed_count: payloadCandidates.filter((candidate) => (
+      candidate.payload?.display_gates?.official_ms_text_student_display_allowed === true
+    )).length,
+    input_diagnostic_count: arrayFrom(inputs.diagnostics).length,
+  };
+}
+
+function buildCandidatesArtifact({
+  paths,
+  generatedAt,
+  sourceArtifacts,
+  payloadCandidates,
+  inputs,
+}) {
+  return {
+    schema_version: CANDIDATES_SCHEMA_VERSION,
+    payload_schema_version:
+      inputs.schema?.payload_schema_version ?? 'post_attempt_review_payload.v1',
+    policy_version: inputs.schema?.policy_version ?? 'post_attempt_review_policy.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    subject_code: SUBJECT_CODE,
+    objective:
+      'Assemble candidate PostAttemptReviewPayload records from checked-in MS source and review artifacts only.',
+    output_artifacts: {
+      candidates: paths.candidatesOut,
+      validator: paths.validatorOut,
+      readback: paths.readbackOut,
+    },
+    source_artifacts: sourceArtifacts,
+    runtime_dependency_boundary: dependencyBoundary(inputs),
+    source_policy: {
+      candidate_links_are_scoring_authority: false,
+      source_spans_are_scoring_authority: false,
+      official_ms_text_embedded_in_payloads: false,
+      source_image_primary_display_allowed: false,
+      accepted_rights_approved_ms_source_screenshot_artifact_present: false,
+    },
+    summary: summarizeCandidates(payloadCandidates, inputs),
+    payload_candidates: payloadCandidates,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        payload_schema_version:
+          inputs.schema?.payload_schema_version ?? 'post_attempt_review_payload.v1',
+        link_ids: payloadCandidates.map((candidate) => candidate.link_id),
+        payloads: payloadCandidates.map((candidate) => candidate.payload),
+        source_artifacts: sourceArtifacts.map((artifact) => ({
+          role: artifact.role,
+          path: artifact.path,
+          sha256: artifact.sha256,
+        })),
+      }),
+    },
+  };
+}
+
+function check(status, id, details = {}) {
+  return { id, status: status ? 'pass' : 'fail', ...details };
+}
+
+function compareCheckIds(left, right) {
+  return Buffer.compare(
+    Buffer.from(String(left.id), 'utf8'),
+    Buffer.from(String(right.id), 'utf8'),
+  );
+}
+
+function pathLooksForbidden(pathValue) {
+  return /(^|\/)(outputs\/screenshots|interactive-messages|\.agent-orchestrator|vector|vectors)(\/|$)/u
+    .test(String(pathValue));
+}
+
+function objectHasOfficialContent(value) {
+  if (Array.isArray(value)) return value.some((item) => objectHasOfficialContent(item));
+  if (!isRecord(value)) return false;
+  return Object.entries(value).some(([key, entry]) => (
+    OFFICIAL_CONTENT_KEYS.has(key) || objectHasOfficialContent(entry)
+  ));
+}
+
+function sourceAssetDisplayAllowed(asset) {
+  return isRecord(asset) &&
+    asset.exists === true &&
+    asset.review_status === 'accepted' &&
+    asset.rights_status === 'display_allowed' &&
+    asset.quality_status === 'accepted';
+}
+
+function primaryDisplayLooksSourceImage(value) {
+  return /source|image|screenshot|official_ms_image|asset/u.test(String(value));
+}
+
+function candidateProvenanceErrors(payloadCandidates) {
+  const errors = [];
+  for (const candidate of payloadCandidates) {
+    const payload = candidate.payload;
+    if (!isRecord(payload)) continue;
+    if (candidate.provenance_status !== 'candidate_provenance_only') {
+      errors.push('candidate_link_not_marked_provenance_only');
+    }
+    if (
+      payload.scoring_posture === 'released_deterministic' ||
+      payload.point_judgement_allowed === true ||
+      payload.authoritative_score_allowed === true ||
+      payload.scoring_authority_ref !== null
+    ) {
+      errors.push('candidate_link_promoted_to_authoritative_score');
+    }
+    if (payload.answer_fact_posture?.answer_fact_allowed === true) {
+      errors.push('candidate_ms_evidence_promoted_to_answer_fact');
+    }
+    if (payload.structured_mark_point_posture?.status === 'accepted') {
+      errors.push('candidate_ms_link_promoted_to_accepted_structured_marks');
+    }
+  }
+  return errors;
+}
+
+function sourceAssetDisplayErrors(payloadCandidates) {
+  const errors = [];
+  for (const candidate of payloadCandidates) {
+    const payload = candidate.payload;
+    if (!isRecord(payload)) continue;
+    if (
+      payload.source_asset?.student_display_allowed === true &&
+      !sourceAssetDisplayAllowed(payload.source_asset)
+    ) {
+      errors.push('source_asset_student_display_without_accepted_rights_approval');
+    }
+    if (
+      payload.display_gates?.official_ms_image_student_display_allowed === true &&
+      !sourceAssetDisplayAllowed(payload.source_asset)
+    ) {
+      errors.push('official_ms_image_student_display_without_accepted_rights_approval');
+    }
+    if (payload.display_gates?.official_ms_text_student_display_allowed === true) {
+      errors.push('official_ms_text_student_display_without_display_license');
+    }
+    if (payload.display_gates?.evidence_drawer_student_display_allowed === true) {
+      errors.push('evidence_drawer_student_display_without_accepted_source_asset');
+    }
+  }
+  return errors;
+}
+
+export function validatePostAttemptMsReviewAdapter({
+  candidates,
+  inputs,
+  sourceArtifacts,
+} = {}) {
+  const errors = [];
+  if (!isRecord(candidates)) errors.push('candidates_required');
+  if (!isRecord(inputs)) errors.push('inputs_required');
+  const artifactsList = Array.isArray(sourceArtifacts) ? sourceArtifacts : [];
+  const payloadCandidates = arrayFrom(candidates?.payload_candidates);
+
+  for (const role of REQUIRED_SOURCE_ROLES) {
+    const artifact = artifactsList.find((item) => item.role === role);
+    if (!(artifact?.exists === true && artifact?.loaded === true)) {
+      errors.push(`${role}_required`);
+    }
+  }
+
+  if (!isRecord(inputs?.schema)) errors.push('post_attempt_review_payload_schema_required');
+  if (!isRecord(inputs?.boundary)) errors.push('post_attempt_ms_review_boundary_required');
+  if (!isRecord(inputs?.questionRuntimeReadModel)) {
+    errors.push('question_runtime_payload_all_3530_read_model_required');
+  }
+  if (!isRecord(inputs?.questionRuntimeManifest)) {
+    errors.push('question_runtime_payload_all_3530_manifest_required');
+  }
+  if (!isRecord(inputs?.msSelectedDocuments)) errors.push('ms_selected_documents_required');
+  if (!isRecord(inputs?.msSourceSpans)) errors.push('ms_source_spans_required');
+  if (!isRecord(inputs?.msRawItems)) errors.push('ms_raw_items_required');
+  if (!isRecord(inputs?.msCandidateLinks)) errors.push('ms_candidate_links_required');
+  if (!isRecord(inputs?.msLayerBReviewQueue)) errors.push('ms_layer_b_review_queue_required');
+  if (!isRecord(inputs?.msReviewQueueTriage)) errors.push('ms_review_queue_triage_required');
+  if (!isRecord(inputs?.semanticReviewQueue)) errors.push('semantic_kg_review_queue_required');
+  if (!isRecord(inputs?.sourceFigureAssetRightsDisplayPolicy)) {
+    errors.push('source_figure_asset_rights_display_policy_required');
+  }
+
+  const runtimeRows = countRows(inputs?.questionRuntimeReadModel, 'rows');
+  if (isRecord(inputs?.questionRuntimeReadModel) && runtimeRows !== EXPECTED_RUNTIME_ROW_COUNT) {
+    errors.push('question_runtime_row_count_not_3530');
+  }
+
+  const livePayloadValidationErrors = [];
+  for (const candidate of payloadCandidates) {
+    const validation = validatePostAttemptReviewPayload({
+      schema: inputs?.schema,
+      payload: candidate?.payload,
+      boundary: inputs?.boundary,
+      fixtureId: candidate?.link_id ?? candidate?.question_key ?? 'unknown',
+    });
+    for (const error of validation.errors) livePayloadValidationErrors.push(error);
+  }
+  for (const error of livePayloadValidationErrors) errors.push(error);
+  const allCandidatesValidate = payloadCandidates.length > 0 &&
+    livePayloadValidationErrors.length === 0;
+
+  const provenanceErrors = candidateProvenanceErrors(payloadCandidates);
+  for (const error of provenanceErrors) errors.push(error);
+
+  const sourceDisplayErrors = sourceAssetDisplayErrors(payloadCandidates);
+  for (const error of sourceDisplayErrors) errors.push(error);
+
+  const noSourceImagePrimaryDisplay = payloadCandidates.every((candidate) => (
+    !primaryDisplayLooksSourceImage(candidate.payload?.primary_display_mode) &&
+    !['source_asset', 'source_image', 'source_ms_screenshot', 'official_ms_image']
+      .includes(arrayFrom(candidate.payload?.learner_display_order)[0])
+  ));
+  if (!noSourceImagePrimaryDisplay) errors.push('source_image_primary_display_detected');
+
+  const requiredArtifactsLoaded = REQUIRED_SOURCE_ROLES.every((role) => {
+    const artifact = artifactsList.find((item) => item.role === role);
+    return artifact?.exists === true && artifact?.loaded === true;
+  });
+
+  const hashesRecorded = artifactsList.every((artifact) => (
+    /^[a-f0-9]{64}$/u.test(String(artifact.sha256))
+  )) && payloadCandidates.every((candidate) => {
+    const hashes = candidate.payload?.generated_from_artifact_hashes;
+    return isRecord(hashes) &&
+      REQUIRED_SOURCE_ROLES.every((role) => /^[a-f0-9]{64}$/u.test(String(hashes[role])));
+  });
